// Estado de un envío de reporte — un solo mapa para todo el producto. El API
// devuelve el ENUM CRUDO EN INGLÉS ('sent' | 'failed' | 'no_data' |
// 'no_recipients' | 'skipped'; así está documentado en
// packages/database/src/schema/reports.ts, report_send_log.status) y el KPI
// "Último envío" lo imprimía tal cual: "estado: sent" en una tira de rótulos en
// español y a 20px del iframe de /settings/reports que YA traduce ese mismo
// enum. Las palabras son EXACTAMENTE las de ese StatusTag (page.tsx) para que el
// KPI y la tabla que tiene debajo no nombren distinto el mismo envío, incluida
// la salida de escape: un valor no mapeado se imprime crudo igual que allí,
// porque sería un bug de nuestro propio lambda y esconderlo lo vuelve invisible.
// `color` viaja con la palabra: el tinte y el texto tienen que salir del mismo
// sitio o vuelven a divergir.
window.ecoSendStatus = function ecoSendStatus(status) {
  const k = String(status || '').toLowerCase().trim();
  if (k === 'sent') return { label: 'enviado', tone: 'pos', color: 'var(--pos)' };
  if (k === 'failed') return { label: 'falló', tone: 'neg', color: 'var(--neg)' };
  if (k === 'no_data') return { label: 'sin datos', tone: 'warn', color: 'var(--warn)' };
  if (k === 'no_recipients') return { label: 'sin destinatarios', tone: 'warn', color: 'var(--warn)' };
  if (k === 'skipped') return { label: 'omitido', tone: 'neutral', color: 'var(--text-3)' };
  return { label: k || '—', tone: 'neutral', color: 'var(--text-3)' };
};

